def _normalize_reduction(reduction):
    if isinstance(reduction, str):
        normalized = _REDUCTION_MAP.get(reduction.lower())
        if normalized is not None:
            return normalized
    elif isinstance(reduction, int) and reduction in (0, 1, 2):
        return reduction
    raise ValueError(
        "multilabel_margin_loss_forward: reduction must be none/mean/sum or 0/1/2"
    )


def _check_inputs(input, target):
    if input.ndim not in (0, 1, 2):
        raise RuntimeError(
            "multilabel_margin_loss_forward: input must be scalar, 1D, or 2D"
        )
    if input.shape != target.shape:
        raise RuntimeError(
            "multilabel_margin_loss_forward: target shape must exactly match input shape"
        )
    if input.device != target.device:
        raise RuntimeError(
            "multilabel_margin_loss_forward: input and target must be on the same device"
        )
    if target.dtype != torch.int64:
        raise RuntimeError(
            "multilabel_margin_loss_forward: target must have dtype torch.int64"
        )
    if input.dtype not in _SUPPORTED_INPUT_DTYPES:
        raise RuntimeError(
            "multilabel_margin_loss_forward: input must have a floating-point loss dtype"
        )

    n_rows = input.shape[0] if input.ndim == 2 else 1
    n_classes = input.shape[-1] if input.ndim != 0 else 1
    if n_classes == 0:
        raise RuntimeError(
            "multilabel_margin_loss_forward: class dimension must be non-empty"
        )
    return n_rows, n_classes


def _empty_batch_result(input, n_classes, reduction):
    is_target = torch.empty(input.shape, dtype=input.dtype, device=input.device)
    if reduction == 0:
        loss = torch.empty((0,), dtype=input.dtype, device=input.device)
    elif reduction == 2:
        loss = torch.zeros((), dtype=input.dtype, device=input.device)
    else:
        loss = torch.full((), float("nan"), dtype=input.dtype, device=input.device)
    return loss, is_target


def multilabel_margin_loss_forward(
    input: torch.Tensor, target: torch.Tensor, reduction=1
):
    logger.debug("GEMS MULTILABEL_MARGIN_LOSS_FORWARD")
    reduction = _normalize_reduction(reduction)
    n_rows, n_classes = _check_inputs(input, target)

    if n_rows == 0:
        return _empty_batch_result(input, n_classes, reduction)

    input_contiguous = input.contiguous()
    target_contiguous = target.contiguous()
    is_target = torch.empty(input.shape, dtype=input.dtype, device=input.device)
    membership = torch.empty(
        (n_rows * n_classes,), dtype=torch.int32, device=input.device
    )
    target_lengths = torch.empty((n_rows,), dtype=torch.int64, device=input.device)
    row_program_limit, loss_program_limit = _get_program_limits()
    validation_grid = min(n_rows, row_program_limit)
    validation_block_r = triton.next_power_of_2(n_rows)
    validation_block_c = triton.next_power_of_2(n_classes)
    use_vector_validation = (
        _IS_ILUVATAR
        and validation_block_r * validation_block_c
        <= _ILUVATAR_VECTOR_VALIDATION_MAX_ELEMENTS
    )
    acc_dtype = torch.float64 if input.dtype == torch.float64 else torch.float32
    acc_fp64 = input.dtype == torch.float64

    scalar_or_vector = input.ndim <= 1
    atomic_row_reduce = (
        use_vector_validation
        and input.dtype == torch.float32
        and not scalar_or_vector
        and reduction != 0
    )
    skip_empty_class_tile = _IS_ASCEND and reduction == 2
    row_reduce_block = min(256, triton.next_power_of_2(n_rows)) if _IS_ILUVATAR else 256
    reduction_divisor = float(n_rows) if reduction == 1 else 1.0
    if scalar_or_vector or reduction == 0:
        loss = torch.empty(
            () if scalar_or_vector else (n_rows,),
            dtype=input.dtype,
            device=input.device,
        )
        row_loss = loss
    elif atomic_row_reduce:
        loss = torch.empty((), dtype=input.dtype, device=input.device)
        row_loss = loss
    else:
        loss = torch.empty((), dtype=input.dtype, device=input.device)
        row_loss = torch.empty((n_rows,), dtype=acc_dtype, device=input.device)

    with torch_device_fn.device(input.device):
        invalid_result = torch.empty(
            (),
            dtype=_INVALID_RESULT_DTYPE,
            device=input.device,
        )
        membership_grid = min(
            triton.cdiv(n_rows * n_classes, _VALIDATION_BLOCK),
            loss_program_limit,
        )
        _clear_membership_kernel[(membership_grid,)](
            membership,
            n_rows * n_classes,
            BLOCK=_VALIDATION_BLOCK,
        )
        if use_vector_validation:
            _build_is_target_vector_kernel[(1,)](
                target_contiguous,
                membership,
                target_lengths,
                invalid_result,
                loss,
                n_rows,
                n_classes,
                INIT_LOSS=atomic_row_reduce,
                RETURN_MAX_TARGET_LENGTH=_RETURN_MAX_TARGET_LENGTH,
                BLOCK_R=validation_block_r,
                BLOCK_C=validation_block_c,
            )
        else:
            invalid_flags = torch.empty(
                (validation_grid,), dtype=torch.int32, device=input.device
            )
            _build_is_target_kernel[(validation_grid,)](
                target_contiguous,
                membership,
                target_lengths,
                invalid_flags,
                n_rows,
                n_classes,
                BLOCK=_VALIDATION_BLOCK,
            )

            invalid_block = triton.next_power_of_2(validation_grid)
            _reduce_invalid_flags_kernel[(1,)](
                invalid_flags,
                target_lengths,
                invalid_result,
                validation_grid,
                n_rows,
                RETURN_MAX_TARGET_LENGTH=_RETURN_MAX_TARGET_LENGTH,
                BLOCK=invalid_block,
            )

        # Synchronizing one scalar is deliberate: invalid targets must raise
        # before any loss kernel is allowed to execute.
        max_target_length = int(invalid_result.item())
        if max_target_length < 0:
            raise RuntimeError(
                "multilabel_margin_loss_forward: target values must be -1 or in [0, C)"
            )

        _membership_to_output_kernel[(membership_grid,)](
            membership,
            is_target,
            n_rows * n_classes,
            BLOCK=_VALIDATION_BLOCK,
        )

        if n_classes <= _FUSED_CLASS_LIMIT:
            loss_grid = min(n_rows, row_program_limit)
            _fused_row_loss_kernel[(loss_grid,)](
                input_contiguous,
                target_contiguous,
                is_target,
                target_lengths,
                row_loss,
                n_rows,
                n_classes,
                reduction_divisor,
                ACC_FP64=acc_fp64,
                ATOMIC_REDUCE=atomic_row_reduce,
                SKIP_EMPTY_CLASS_TILE=skip_empty_class_tile,
                BLOCK_C=_LOSS_CLASS_BLOCK,
                BLOCK_T=_BACKEND_LOSS_TARGET_BLOCK,
            )
        else:
            class_tiles = triton.cdiv(n_classes, _LOSS_CLASS_BLOCK)
            full_target_tiles = triton.cdiv(n_classes, _BACKEND_LOSS_TARGET_BLOCK)
            target_tiles = full_target_tiles
            if _IS_ASCEND and reduction in (0, 1):
                active_target_tiles = triton.cdiv(
                    max_target_length, _BACKEND_LOSS_TARGET_BLOCK
                )
                target_tiles = (
                    min(
                        full_target_tiles,
                        triton.next_power_of_2(active_target_tiles),
                    )
                    if active_target_tiles > 0
                    else 1
                )
            use_class_tiled_loss = _IS_ASCEND and reduction == 2
            if use_class_tiled_loss:
                tiles_per_row = class_tiles
            else:
                tiles_per_row = class_tiles * target_tiles
            total_tiles = n_rows * tiles_per_row
            partial = torch.empty((total_tiles,), dtype=acc_dtype, device=input.device)
            tiled_grid = min(total_tiles, loss_program_limit)
            if use_class_tiled_loss:
                _class_tiled_loss_kernel[(tiled_grid,)](
                    input_contiguous,
                    target_contiguous,
                    is_target,
                    target_lengths,
                    partial,
                    n_classes,
                    class_tiles,
                    total_tiles,
                    ACC_FP64=acc_fp64,
                    BLOCK_C=_LOSS_CLASS_BLOCK,
                    BLOCK_T=_BACKEND_LOSS_TARGET_BLOCK,
                )
            else:
                _tiled_loss_kernel[(tiled_grid,)](
                    input_contiguous,
                    target_contiguous,
                    is_target,
                    target_lengths,
                    partial,
                    n_classes,
                    class_tiles,
                    target_tiles,
                    total_tiles,
                    ACC_FP64=acc_fp64,
                    BLOCK_C=_LOSS_CLASS_BLOCK,
                    BLOCK_T=_BACKEND_LOSS_TARGET_BLOCK,
                )
            row_grid = min(n_rows, row_program_limit)
            _reduce_tiled_rows_kernel[(row_grid,)](
                partial,
                row_loss,
                n_rows,
                tiles_per_row,
                n_classes,
                reduction_divisor,
                ACC_FP64=acc_fp64,
                ATOMIC_REDUCE=atomic_row_reduce,
                BLOCK=256,
            )

        if not scalar_or_vector and reduction != 0 and not atomic_row_reduce:
            _reduce_rows_kernel[(1,)](
                row_loss,
                loss,
                n_rows,
                reduction_divisor,
                ACC_FP64=acc_fp64,
                BLOCK=row_reduce_block,
            )

    return loss, is_target


@libentry()
@triton.jit
def _multilabel_margin_loss_forward_backward_kernel(
    x_ptr,
    target_ptr,
    is_target_ptr,
    grad_ptr,
    grad_output_ptr,
    n_classes,
    x_row_stride,
    x_class_stride,
    target_row_stride,
    target_class_stride,
    is_target_row_stride,
    is_target_class_stride,
    grad_row_stride,
    grad_class_stride,
    grad_output_stride,
    mean_divisor,
    ACC_FP64: tl.constexpr,
    BLOCK_T: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Differentiate one row/class tile in one completely fused dispatch."""
    row = tl.program_id(0)
    tile = tl.program_id(1)
    x_base = row * x_row_stride
    target_base = row * target_row_stride
    is_target_base = row * is_target_row_stride
    grad_base = row * grad_row_stride

    if ACC_FP64:
        acc_type: tl.constexpr = tl.float64
    else:
        acc_type: tl.constexpr = tl.float32

    grad_output = tl.load(grad_output_ptr + row * grad_output_stride).to(acc_type)
    scale = grad_output / (tl.full((), 1.0, dtype=acc_type) * n_classes * mean_divisor)

    own_offsets = tile * BLOCK + tl.arange(0, BLOCK)
    own_mask = own_offsets < n_classes
    x_own = tl.load(
        x_ptr + x_base + own_offsets * x_class_stride,
        mask=own_mask,
        other=0.0,
    )
    own_membership = tl.load(
        is_target_ptr + is_target_base + own_offsets * is_target_class_stride,
        mask=own_mask,
        other=1.0,
    )
    own_is_non_target = own_mask & (own_membership == 0.0)

    # Find the active target-prefix end once, and recover the multiplicity of
    # every class owned by this program directly from that prefix.
    target_stop = n_classes
    for target_start in range(0, n_classes, BLOCK_T):
        target_offsets = target_start + tl.arange(0, BLOCK_T)
        target_mask = target_offsets < n_classes
        target_ids = tl.load(
            target_ptr + target_base + target_offsets * target_class_stride,
            mask=target_mask,
            other=-1,
        )
        block_stop = tl.min(
            tl.where(target_mask & (target_ids < 0), target_offsets, n_classes),
            axis=0,
        )
        target_stop = tl.minimum(target_stop, block_stop)

    own_multiplicity = tl.zeros((BLOCK,), dtype=tl.int32)
    for target_start in range(0, target_stop, BLOCK_T):
        target_offsets = target_start + tl.arange(0, BLOCK_T)
        target_mask = target_offsets < target_stop
        target_ids = tl.load(
            target_ptr + target_base + target_offsets * target_class_stride,
            mask=target_mask,
            other=-2,
        )
        own_multiplicity += tl.sum(
            ((target_ids[:, None] == own_offsets[None, :]) & target_mask[:, None]).to(
                tl.int32
            ),
            axis=0,
        )

    if ACC_FP64:
        accumulator = tl.zeros((BLOCK,), dtype=tl.float64)
        own_multiplicity_weight = own_multiplicity.to(tl.float64)
    else:
        accumulator = tl.zeros((BLOCK,), dtype=tl.float32)
        own_multiplicity_weight = own_multiplicity.to(tl.float32)

    # First derivative term: an active own class is the left side of every
    # hinge against the row's non-target classes.
    own_is_target = own_multiplicity > 0
    if tl.sum(own_is_target.to(tl.int32), axis=0) != 0:
        for other_start in range(0, n_classes, BLOCK):
            other_offsets = other_start + tl.arange(0, BLOCK)
            other_mask = other_offsets < n_classes
            other_membership = tl.load(
                is_target_ptr + is_target_base + other_offsets * is_target_class_stride,
                mask=other_mask,
                other=1.0,
            )
            other_is_non_target = other_mask & (other_membership == 0.0)
            if tl.sum(other_is_non_target.to(tl.int32), axis=0) != 0:
                x_other = tl.load(
                    x_ptr + x_base + other_offsets * x_class_stride,
                    mask=other_mask,
                    other=0.0,
                )
                one = tl.full((BLOCK,), 1.0, x_ptr.dtype.element_ty)
                margin = ((one - x_own)[:, None] + x_other[None, :]).to(
                    x_ptr.dtype.element_ty
                )
                active = (
                    (margin > 0.0)
                    & own_is_target[:, None]
                    & other_is_non_target[None, :]
                )
                accumulator -= tl.sum(
                    tl.where(active, own_multiplicity_weight[:, None], 0.0),
                    axis=1,
                )

    # Mirrored term: a non-target own class is the right side of every hinge.
    # Iterating the target prefix itself makes duplicate target IDs contribute
    # once per occurrence, so no separate multiplicity tensor is needed.
    if tl.sum(own_is_non_target.to(tl.int32), axis=0) != 0:
        for target_start in range(0, target_stop, BLOCK_T):
            target_offsets = target_start + tl.arange(0, BLOCK_T)
            target_mask = target_offsets < target_stop
            target_ids = tl.load(
                target_ptr + target_base + target_offsets * target_class_stride,
                mask=target_mask,
                other=0,
            )
            x_target = tl.load(
                x_ptr + x_base + target_ids * x_class_stride,
                mask=target_mask,
                other=0.0,
            )
            one = tl.full((BLOCK_T,), 1.0, x_ptr.dtype.element_ty)
            margin = ((one - x_target)[:, None] + x_own[None, :]).to(
                x_ptr.dtype.element_ty
            )
            active = (margin > 0.0) & target_mask[:, None] & own_is_non_target[None, :]
            accumulator += tl.sum(active.to(acc_type), axis=0)

    tl.store(
        grad_ptr + grad_base + own_offsets * grad_class_stride,
        accumulator * scale,
        mask=own_mask,
    )


def _backward_row_class(tensor):
    if tensor.dim() == 0:
        return 1, 1
    if tensor.dim() == 1:
        return 1, int(tensor.shape[0])
    return int(tensor.shape[0]), int(tensor.shape[1])


def _backward_strides(tensor):
    if tensor.dim() == 0:
        return 1, 1
    if tensor.dim() == 1:
        return 0, tensor.stride(0)
    return tensor.stride(0), tensor.stride(1)


def _backward_block(rows, n_classes):
    for block in _BACKWARD_BLOCK_CANDIDATES:
        if rows * triton.cdiv(n_classes, block) >= _BACKWARD_MIN_PROGRAMS:
            return block
    if n_classes < _BACKWARD_BLOCK_CANDIDATES[-1]:
        return max(16, triton.next_power_of_2(n_classes))
    return _BACKWARD_BLOCK_CANDIDATES[-1]


def multilabel_margin_loss_forward_backward(
    grad_output: torch.Tensor,
    input: torch.Tensor,
    target: torch.Tensor,
    reduction: int,
    is_target: torch.Tensor,
):
    """Pure Triton derivative used by the custom forward autograd node."""
    logger.debug("GEMS MULTILABEL_MARGIN_LOSS_FORWARD_BACKWARD")
    reduction = _normalize_reduction(reduction)
    if input.dim() > 2 or input.dtype not in _SUPPORTED_INPUT_DTYPES:
        raise RuntimeError(
            "multilabel_margin_loss_forward_backward: input must be a floating "
            "scalar, vector or matrix"
        )
    if (
        target.device != input.device
        or is_target.device != input.device
        or grad_output.device != input.device
    ):
        raise RuntimeError(
            "multilabel_margin_loss_forward_backward: all tensors must share a device"
        )
    rows, n_classes = _backward_row_class(input)
    if tuple(target.shape) != tuple(input.shape) or tuple(is_target.shape) != tuple(
        input.shape
    ):
        raise RuntimeError(
            "multilabel_margin_loss_forward_backward: saved tensors must match input"
        )
    if target.dtype != torch.int64 or is_target.dtype != input.dtype:
        raise RuntimeError(
            "multilabel_margin_loss_forward_backward: invalid saved tensor dtype"
        )
    if n_classes == 0:
        raise RuntimeError(
            "multilabel_margin_loss_forward_backward: class dimension must be non-empty"
        )
    if rows == 0:
        return torch.empty_like(input)
    if reduction == 0 and grad_output.dim() > 0 and grad_output.numel() != rows:
        raise RuntimeError(
            "multilabel_margin_loss_forward_backward: expected one grad per row"
        )

    grad_input = torch.empty_like(input, memory_format=torch.preserve_format)
    xrs, xcs = _backward_strides(input)
    trs, tcs = _backward_strides(target)
    irs, ics = _backward_strides(is_target)
    grs, gcs = _backward_strides(grad_input)
    grad_output_stride = (
        grad_output.stride(0) if reduction == 0 and grad_output.dim() == 1 else 0
    )
    block = _backward_block(rows, n_classes)
    grid = (rows, triton.cdiv(n_classes, block))
    with torch_device_fn.device(input.device):
        _multilabel_margin_loss_forward_backward_kernel[grid](
            input,
            target,
            is_target,
            grad_input,
            grad_output,
            n_classes,
            xrs,
            xcs,
            trs,
            tcs,
            irs,
            ics,
            grs,
            gcs,
            grad_output_stride,
            rows if reduction == 1 else 1,
            ACC_FP64=input.dtype == torch.float64,
            BLOCK_T=_BACKWARD_TARGET_BLOCK,
            BLOCK=block,
        )
    return grad_input


_multilabel_margin_loss_forward_impl = multilabel_margin_loss_forward


class MultilabelMarginLossForwardFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, target, reduction):
        normalized_reduction = _normalize_reduction(reduction)
        loss, is_target = _multilabel_margin_loss_forward_impl(
            input, target, normalized_reduction
        )
        ctx.reduction = normalized_reduction
        ctx.save_for_backward(input, target, is_target)
        ctx.mark_non_differentiable(is_target)
        ctx.set_materialize_grads(False)
        return loss, is_target

    @staticmethod
    def backward(ctx, grad_loss, grad_is_target):
        input, target, is_target = ctx.saved_tensors
        grad_input = multilabel_margin_loss_forward_backward(
            grad_loss, input, target, ctx.reduction, is_target
        )
        return grad_input, None, None


def multilabel_margin_loss_forward(
    input: torch.Tensor, target: torch.Tensor, reduction=1
):
    logger.debug("GEMS MULTILABEL_MARGIN_LOSS_FORWARD")
    if torch.is_grad_enabled() and input.requires_grad:
        return MultilabelMarginLossForwardFunction.apply(input, target, reduction)
    return _multilabel_margin_loss_forward_impl(input, target, reduction)
